import time
from functools import wraps

def medir_tempo(funcao):
    @wraps(funcao)
    def wrapper(*args, **kwargs):
        inicio = time.time()
        resultado = funcao(*args, **kwargs)
        duracao = time.time() - inicio
        print(f'{funcao.__name__} levou {duracao:.4f} segundos')
        return resultado
    return wrapper

@medir_tempo
def somar_ate(n):
    return sum(range(n + 1))

print(somar_ate(1000000))

class Animal:
    def __init__(self, nome):
        self.nome = nome

    def fazer_som(self):
        return 'Algum som generico'

class Cachorro(Animal):
    def fazer_som(self):
        return 'Au au!'

class Gato(Animal):
    def fazer_som(self):
        som_original = super().fazer_som()
        return f'{som_original} (na verdade, Miau!)'

rex = Cachorro('Rex')
mimi = Gato('Mimi')
print(rex.nome, '->', rex.fazer_som())   # Rex -> Au au!
print(mimi.nome, '->', mimi.fazer_som()) # Mimi -> Algum som generico (na verdade, Miau!)

class Carrinho:
    def __init__(self, itens=None):
        self.itens = itens or []

    def __str__(self):
        return f'Carrinho com {len(self.itens)} item(ns)'

    def __repr__(self):
        return f'Carrinho(itens={self.itens!r})'

    def __len__(self):
        return len(self.itens)

carrinho = Carrinho(['livro', 'caneta'])
print(carrinho)        # usa __str__: Carrinho com 2 item(ns)
print(repr(carrinho))  # usa __repr__: Carrinho(itens=['livro', 'caneta'])
print(len(carrinho))   # usa __len__: 2

from typing import List, Optional

def calcular_media(numeros: List[float]) -> float:
    return sum(numeros) / len(numeros)

def buscar_usuario(id_usuario: int) -> Optional[str]:
    usuarios = {1: 'Ana', 2: 'Bruno'}
    return usuarios.get(id_usuario)  # pode devolver None

media: float = calcular_media([7.5, 8.0, 9.2])
print(media)
print(buscar_usuario(3))  # None, e o type hint avisa que isso e esperado

class SaldoInsuficienteError(Exception):
    """Erro levantado quando uma conta nao tem saldo suficiente."""
    pass

class Conta:
    def __init__(self, saldo):
        self.saldo = saldo

    def sacar(self, valor):
        if valor > self.saldo:
            raise SaldoInsuficienteError(f'Saldo de {self.saldo} e insuficiente para sacar {valor}')
        self.saldo -= valor

conta = Conta(100)
try:
    conta.sacar(150)
except SaldoInsuficienteError as erro:
    print('Nao foi possivel sacar:', erro)
except Exception as erro:
    print('Erro inesperado:', erro)

nomes = ['Ana', 'Bruno', 'Carla', 'ana']

# Compreensao de dicionario: mapeia cada nome ao seu tamanho
tamanhos = {nome: len(nome) for nome in nomes}
print(tamanhos)  # {'Ana': 3, 'Bruno': 5, 'Carla': 5, 'ana': 3}

# Compreensao de conjunto: nomes unicos em minusculas
nomes_unicos = {nome.lower() for nome in nomes}
print(nomes_unicos)  # {'ana', 'bruno', 'carla'}

# Com condicao if, como na list comprehension
maiores_que_3 = {nome: tamanho for nome, tamanho in tamanhos.items() if tamanho > 3}
print(maiores_que_3)  # {'Bruno': 5, 'Carla': 5}
